package ai.elizaresearch.alphaphone;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * English text to Kokoro-82M en-US IPA phrases, entirely in Java: no eSpeak, no network, no extra runtime.
 *
 * <p>Words come from a pinned lexicon generated by scripts/android-voice-lexicon.mjs from the
 * BSD-2-Clause CMU Pronouncing Dictionary (cmusphinx/cmudict 74790861f652b15e4ac49015a90074ad62a27690)
 * with a deterministic ARPAbet to misaki-style symbol mapping. Numbers become English cardinal
 * words; any other unknown word is spelled letter by letter. Unsupported symbols fail closed
 * instead of being dropped silently.
 *
 * <p>Intelligibility is unqualified: no listening test or synthesis-to-recognition gate has
 * accepted this front end. It is the documented workaround for the missing upstream Android G2P.
 *
 * <p>The lexicon is held as one byte array with a line-offset index (about 3 MB plus 0.5 MB), not
 * a map of strings, and is dropped with the speech engine on idle or memory pressure.
 */
final class AlphaKokoroG2p {
 static final int MAX_LEXICON_BYTES=8*1024*1024;
 private static final Pattern TOKENS=Pattern.compile("[A-Za-z]+(?:'[A-Za-z]+)*|[0-9]+|[.,!?;:]|[()\\[\\]\"“”‘’'—–-]|\\S");
 private static final String[] LETTERS={"ˈA","bˈi","sˈi","dˈi","ˈi","ˈɛf","ʤˈi","ˈAʧ","ˈI","ʤˈA","kˈA","ˈɛl","ˈɛm","ˈɛn","ˈO","pˈi","kjˈu","ˈɑɹ","ˈɛs","tˈi","jˈu","vˈi","dˈʌbəlju","ˈɛks","wˈI","zˈi"};
 private static final String[] ONES={"zero","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"};
 private static final String[] TENS={"","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"};
 private final byte[] data;
 private final int[] lines;

 AlphaKokoroG2p(File lexicon)throws IOException{
  if(!lexicon.isFile()||lexicon.length()<=0||lexicon.length()>MAX_LEXICON_BYTES)throw new IOException("Voice lexicon missing or oversized");
  byte[] bytes=new byte[(int)lexicon.length()];
  try(InputStream in=new FileInputStream(lexicon)){int offset=0,n;while(offset<bytes.length&&(n=in.read(bytes,offset,bytes.length-offset))>0)offset+=n;if(offset!=bytes.length||in.read()!=-1)throw new IOException("Voice lexicon changed while loading");}
  this.data=bytes;this.lines=index(bytes);
 }
 /** Validates the generated format: sorted unique lowercase words, a tab, a non-empty IPA field. */
 private static int[] index(byte[] bytes)throws IOException{
  if(bytes.length==0||bytes[bytes.length-1]!='\n')throw new IOException("Voice lexicon is not newline terminated");
  int count=0;for(byte b:bytes)if(b=='\n')count++;
  int[] starts=new int[count];int line=0,start=0,previous=-1;
  for(int i=0;i<bytes.length;i++){
   if(bytes[i]!='\n')continue;
   int tab=-1;for(int j=start;j<i;j++){byte b=bytes[j];if(b=='\t'){tab=j;break;}if(!(b>='a'&&b<='z')&&b!='\'')throw new IOException("Voice lexicon word is not lowercase English");}
   if(tab<=start||tab>=i-1)throw new IOException("Voice lexicon row is malformed");
   if(previous>=0&&compare(bytes,previous,word(bytes,previous),bytes,start,tab-start)>=0)throw new IOException("Voice lexicon is not sorted and unique");
   starts[line++]=start;previous=start;start=i+1;
  }
  return starts;
 }
 private static int word(byte[] bytes,int start){int end=start;while(bytes[end]!='\t')end++;return end-start;}
 private static int compare(byte[] a,int aStart,int aLength,byte[] b,int bStart,int bLength){int n=Math.min(aLength,bLength);for(int i=0;i<n;i++){int d=(a[aStart+i]&255)-(b[bStart+i]&255);if(d!=0)return d;}return aLength-bLength;}
 int entries(){return lines.length;}
 /** The IPA for one lowercase word, or null. */
 String lookup(String word){
  byte[] key=word.getBytes(StandardCharsets.US_ASCII);int low=0,high=lines.length-1;
  while(low<=high){int mid=(low+high)>>>1,start=lines[mid],length=word(data,start);int c=compare(data,start,length,key,0,key.length);
   if(c==0){int ipa=start+length+1,end=ipa;while(data[end]!='\n')end++;return new String(data,ipa,end-ipa,StandardCharsets.UTF_8);}
   if(c<0)low=mid+1;else high=mid-1;}
  return null;
 }
 /** Spoken English words for 0..999,999,999; longer digit runs are read digit by digit. */
 static List<String> numberWords(String digits){
  List<String> out=new ArrayList<>();
  if(digits.length()>9||(digits.length()>1&&digits.charAt(0)=='0')){for(char c:digits.toCharArray())out.add(ONES[c-'0']);return out;}
  int value=Integer.parseInt(digits);if(value==0){out.add("zero");return out;}
  int millions=value/1_000_000,thousands=(value/1000)%1000,rest=value%1000;
  if(millions>0){hundreds(millions,out);out.add("million");}
  if(thousands>0){hundreds(thousands,out);out.add("thousand");}
  if(rest>0)hundreds(rest,out);
  return out;
 }
 private static void hundreds(int value,List<String> out){
  if(value>=100){out.add(ONES[value/100]);out.add("hundred");value%=100;}
  if(value>=20){out.add(TENS[value/10]);if(value%10>0)out.add(ONES[value%10]);}
  else if(value>0)out.add(ONES[value]);
 }
 private String word(String lower){
  String ipa=lookup(lower);if(ipa!=null)return ipa;
  StringBuilder spelled=new StringBuilder();
  for(char letter:lower.toCharArray()){if(letter=='\'')continue;if(letter<'a'||letter>'z')throw new IllegalArgumentException("Local speech currently supports English text; unsupported symbol");if(spelled.length()>0)spelled.append(' ');spelled.append(LETTERS[letter-'a']);}
  if(spelled.length()==0)throw new IllegalArgumentException("Local speech currently supports English text; unsupported symbol");
  return spelled.toString();
 }
 /**
  * Text to phrases of at most {@link AlphaSpeechText#PHRASE_TARGET} IPA symbols. A phrase ends at
  * sentence punctuation, or at the last word that fits. Throws for unsupported input before any
  * audio is produced.
  */
 List<String> phrases(String text){
  if(text==null||text.isBlank()||text.length()>AlphaSpeechText.MAX_PASSAGE||text.indexOf('\0')>=0)throw new IllegalArgumentException("Expected 1 to 5000 text characters");
  List<String> phrases=new ArrayList<>();StringBuilder phrase=new StringBuilder();Matcher tokens=TOKENS.matcher(text);
  while(tokens.find()){
   String token=tokens.group();char first=token.charAt(0);
   if(".!?".indexOf(first)>=0&&token.length()==1){if(phrase.length()>0){phrase.append(first);flush(phrase,phrases);}continue;}
   if(",;:".indexOf(first)>=0&&token.length()==1){if(phrase.length()>0&&phrase.length()<AlphaSpeechText.PHRASE_TARGET)phrase.append(first);continue;}
   if(token.length()==1&&"()[]\"“”‘’'".indexOf(first)>=0)continue;
   if(token.length()==1&&"—–-".indexOf(first)>=0){if(phrase.length()>0&&phrase.length()<AlphaSpeechText.PHRASE_TARGET&&",;:".indexOf(phrase.charAt(phrase.length()-1))<0)phrase.append(',');continue;}
   List<String> spoken=new ArrayList<>();
   if(Character.isDigit(first)){for(String number:numberWords(token))spoken.add(word(number));}
   else if((first>='A'&&first<='Z')||(first>='a'&&first<='z'))spoken.add(word(token.toLowerCase(Locale.ROOT)));
   else throw new IllegalArgumentException("Local speech currently supports English text; unsupported symbol");
   for(String ipa:spoken){
    if(ipa.length()>AlphaSpeechText.PHRASE_TARGET)throw new IllegalArgumentException("A word is too long for local speech");
    if(phrase.length()>0&&phrase.length()+1+ipa.length()>AlphaSpeechText.PHRASE_TARGET)flush(phrase,phrases);
    if(phrase.length()>0)phrase.append(' ');phrase.append(ipa);
   }
  }
  flush(phrase,phrases);
  if(phrases.isEmpty())throw new IllegalArgumentException("Nothing to speak");
  return phrases;
 }
 private static void flush(StringBuilder phrase,List<String> phrases){if(phrase.length()==0)return;phrases.add(AlphaSpeechText.requirePhrase(phrase.toString()));phrase.setLength(0);}
 /** Releases the in-memory lexicon. */
 void clear(){Arrays.fill(data,(byte)0);}
}
